//! Exact locations in disposable multilingual scenes; invoked by desk_tests.
use super::*;
fn request(p:&Rc<EditorPane>,value:Value,editing:bool)->Value{let result=Rc::new(RefCell::new(None));let out=result.clone();p.request(value,editing,move|reply|*out.borrow_mut()=Some(reply));wait(||result.borrow().is_some()&&p.pending.get()==0);let value=result.borrow_mut().take().unwrap().unwrap();value}
fn location(p:&Rc<EditorPane>)->Value{request(p,json!({"type":"command","command":"captureNavigation","followCursor":false}),false)["navigationCapture"].clone()}
fn set_location(p:&Rc<EditorPane>,anchor:[usize;2],cursor:[usize;2],top:u64)->(Value,u64){
    let mut capture=location(p);capture["anchor"]=json!(anchor);capture["cursor"]=json!(cursor);let frame=request(p,json!({"type":"command","command":"restoreNavigation","bookmark":capture,"top":top,"followCursor":false}),false);assert_eq!(frame["top"],top);
    let document=p.frame.borrow()["document"].clone();let first=novel_storage::plain_text(&document["content"][anchor[0]]).chars().skip(anchor[1]).collect::<String>();let last=novel_storage::plain_text(&document["content"][cursor[0]]).chars().take(cursor[1]).collect::<String>();assert_eq!(frame["selectedText"],format!("{first}\n{last}"));(location(p),top)
}
fn show(a:&Rc<Workspace>,id:&str)->Rc<EditorPane>{a.open_scene(id,false);wait(||!a.desk.busy.get()&&a.active.borrow().as_ref().is_some_and(|p|p.scene_id==id&&p.open.get()&&p.pending.get()==0)&&a.current_widget()==a.active.borrow().as_ref().map(|p|p.widget.clone().upcast()));a.active.borrow().clone().unwrap()}
fn rich(title:&str)->Value{json!({"schemaVersion":1,"title":title,"document":{"type":"doc","content":(0..80).map(|i|json!({"type":"paragraph","attrs":{"dir":if i%2==0{"rtl"}else{"ltr"},"lang":if i%2==0{"ar"}else{"zh-Hans"},"lineSpacing":1.5},"content":[{"type":"text","text":format!("Paragraph {i}: مِ 中文 𠀀 👩🏽‍🚀 e\u{301}"),"marks":[{"type":"bold"},{"type":"underline"}]}]})).collect::<Vec<_>>()}})}
pub(super) fn run(binaries:&Path){
    let fixture=tempfile::tempdir().unwrap();let data=fixture.path().join("navigation-data");let cache=fixture.path().join("navigation-cache");std::fs::create_dir_all(&data).unwrap();std::fs::create_dir_all(&cache).unwrap();
    let companion=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=Process::start(&binaries.join(companion),&data,true).unwrap();let novel=rpc(&client,"create_novel",json!({"title":"Exact navigation"}));let first_id=novel["scene"]["id"].as_str().unwrap();let pid=novel["project"]["id"].as_str().unwrap();let cid=novel["scene"]["chapterId"].as_str().unwrap();
    let initial=rpc(&client,"load_scene",json!({"sceneId":first_id}));let first_saved=rpc(&client,"save_scene",json!({"sceneId":first_id,"scene":rich("First مِ 中文"),"parent":initial["revisionId"]}));let second=rpc(&client,"create_scene",json!({"chapterId":cid,"scene":rich("Second مِ 中文")}));let second_id=second["id"].as_str().unwrap();let third=rpc(&client,"create_scene",json!({"chapterId":cid,"scene":{"schemaVersion":1,"title":"New branch","document":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Branch مِ 中文"}]}]}}}));let third_id=third["id"].as_str().unwrap();
    let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||a.active.borrow().as_ref().is_some_and(|p|p.scene_id==first_id&&p.open.get()&&p.pending.get()==0));let first=a.active.borrow().clone().unwrap();let (first_location,first_top)=set_location(&first,[30,14],[31,26],200);
    let marker=rpc(&a.client,"sync_cursor",json!({}));let second=show(&a,second_id);let (second_location,second_top)=set_location(&second,[40,17],[41,29],300);assert_eq!(a.trail.borrow().len(),2);assert_eq!(a.trail_index.get(),1);
    a.back();wait(||!a.desk.busy.get()&&a.current_widget()==Some(first.widget.clone().upcast()));assert_eq!(location(&first),first_location);assert_eq!(first.frame.borrow()["top"],first_top);assert_eq!(a.trail_index.get(),0);
    a.forward();wait(||!a.desk.busy.get()&&a.current_widget()==Some(second.widget.clone().upcast()));assert_eq!(location(&second),second_location);assert_eq!(second.frame.borrow()["top"],second_top);assert_eq!(a.trail_index.get(),1);assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":first_id})),first_saved);
    // Cancel preserves the current dirty draft, trail index and selection exactly.
    edit(&second,"Saved by explicit choice مِ 中文 𠀀 👩🏽‍🚀");let dirty_location=location(&second);let dirty_top=second.frame.borrow()["top"].clone();let dirty_document=second.frame.borrow()["document"].clone();select(&a,SaveChoice::Cancel);a.back();assert_eq!(a.current_widget(),Some(second.widget.clone().upcast()));assert_eq!(a.trail_index.get(),1);assert_eq!(location(&second),dirty_location);assert!(second.dirty.get());assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    select(&a,SaveChoice::Save);a.back();wait(||!a.desk.busy.get()&&a.current_widget()==Some(first.widget.clone().upcast()));assert!(!second.dirty.get());let second_saved=rpc(&a.client,"load_scene",json!({"sceneId":second_id}));assert_eq!(second_saved["scene"]["document"],dirty_document);assert_eq!(location(&first),first_location);assert_eq!(first.frame.borrow()["top"],first_top);
    let marker=rpc(&a.client,"sync_cursor",json!({}));a.forward();wait(||!a.desk.busy.get()&&a.current_widget()==Some(second.widget.clone().upcast()));assert_eq!(location(&second),dirty_location);assert_eq!(second.frame.borrow()["top"],dirty_top);assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    // Discard captures the restored saved document, never discarded draft offsets.
    edit(&second,"Discarded changes مِ 中文");select(&a,SaveChoice::Discard);a.back();wait(||!a.desk.busy.get()&&a.current_widget()==Some(first.widget.clone().upcast()));assert!(!second.dirty.get());assert_eq!(second.frame.borrow()["document"],dirty_document);let discarded_location=location(&second);let discarded_top=second.frame.borrow()["top"].clone();
    a.forward();wait(||!a.desk.busy.get()&&a.current_widget()==Some(second.widget.clone().upcast()));assert_eq!(location(&second),discarded_location);assert_eq!(second.frame.borrow()["top"],discarded_top);assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    // An older entry cannot overwrite offsets in a changed cached target document.
    edit(&first,"Changed hidden draft مِ 中文");let changed=location(&first);let current=a.current_widget();a.back();wait(||!a.desk.busy.get());assert_eq!(a.current_widget(),current);assert_eq!(a.trail_index.get(),1);assert_eq!(location(&first),changed);assert!(first.dirty.get());assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    let done=Rc::new(Cell::new(false));let out=done.clone();first.discard(move|result|{result.unwrap();out.set(true);});wait(||done.get());a.back();wait(||!a.desk.busy.get()&&a.current_widget()==Some(first.widget.clone().upcast()));assert_eq!(location(&first),first_location);assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":first_id})),first_saved);
    // New navigation from an earlier entry cuts off the former Forward branch.
    let third=show(&a,third_id);assert_eq!(a.trail.borrow().iter().map(|entry|entry.scene_id.clone()).collect::<Vec<_>>(),vec![first_id.to_owned(),third_id.to_owned()]);assert_eq!(a.trail_index.get(),1);let current=a.current_widget();a.forward();assert_eq!(a.current_widget(),current);assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    // A newer saved revision refuses a cached entry even when its old document hash matches.
    rpc(&a.client,"rename_scene",json!({"sceneId":first_id,"title":"New saved title مِ 中文","parent":first_saved["revisionId"]}));let marker=rpc(&a.client,"sync_cursor",json!({}));let unchanged=location(&first);a.back();wait(||!a.desk.busy.get());assert_eq!(a.current_widget(),current);assert_eq!(a.trail_index.get(),1);assert_eq!(location(&first),unchanged);assert!(a.status.text().contains("saved scene changed"));assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    // Composition and outstanding editor work prevent departure captures outright.
    third.composing.set(true);let result=Rc::new(Cell::new(None));let out=result.clone();a.capture_departure(move|ok|out.set(Some(ok)));assert_eq!(result.get(),Some(false));assert_eq!(a.current_widget(),current);third.composing.set(false);
    third.pending.set(1);let result=Rc::new(Cell::new(None));let out=result.clone();a.capture_departure(move|ok|out.set(Some(ok)));assert_eq!(result.get(),Some(false));assert_eq!(a.current_widget(),current);third.pending.set(0);assert_eq!(a.trail_index.get(),1);assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":second_id})),second_saved);assert_eq!(rpc(&a.client,"open_project_index",json!({"projectId":pid}))["scenes"].as_array().unwrap().len(),3);a.close();wait(||windows()==0);
}
